  ('kestrel', 'Kestrel Aerostructures', 'Manufacturing', '~1,800 staff', 'Western Canada', 'Aircraft-parts manufacturer automating its machining lines and running an apprenticeship program.', '~40 open roles, incl. 6 apprenticeships (sample)', array['reskilling', 'pipeline']::text[], 'yyyy?yy?', false, '{"problems":[{"title":"Reskilling","detail":"Automation is changing machinist roles; some staff need a path into programming, inspection or maintenance."},{"title":"Workforce pipeline","detail":"Apprentices choose a trade early and some drop out when it doesn''t suit them."}],"evidence":[{"text":"Posted six apprenticeship openings and a \"Workforce Development Coordinator\" role.","source":"Job postings (sample)"},{"text":"Announced a two-year automation upgrade of its main plant.","source":"News release (sample)"},{"text":"Training budget is managed by a single L&D lead.","source":"LinkedIn (sample)"}],"unknowns":["Does the L&D lead have budget authority for new tools?","How many apprentices leave in their first year?"],"roles":["Workforce Development Coordinator","Manager, Learning & Development","VP Operations"],"fitConcerns":["Manufacturing staff may prefer hands-on assessments to an online sandbox."]}'::jsonb),
  ('prairiehealth', 'Prairie Health Network', 'Healthcare employer', '~6,000 staff', 'Western Canada', 'Regional health employer with ongoing turnover in nursing and allied-health roles.', '~120 open roles (sample)', array['retention', 'pipeline']::text[], 'yyyy?y??', false, '{"problems":[{"title":"Employee retention","detail":"First-year turnover in frontline roles is costly; staff who feel stuck leave for other employers."},{"title":"Workforce pipeline","detail":"They need to steer existing staff toward hard-to-fill roles rather than only hiring externally."}],"evidence":[{"text":"Posted a job for a \"Retention and Engagement Specialist\".","source":"Job posting (sample)"},{"text":"Announced an internal mobility program for support staff moving into clinical roles.","source":"News release (sample)"},{"text":"Local news coverage of nurse turnover in rural sites.","source":"News article (sample)"}],"unknowns":["Who owns the internal mobility program: HR, Learning & Development, or a clinical department?","Is there funding attached to the retention role?","Would a union need to be consulted?"],"roles":["VP People & Culture","Director, Learning & Development","Retention and Engagement Specialist (influencer)"],"fitConcerns":["Large employer: the first person reached may not have authority.","Health systems may prefer tools already in their HR platform."]}'::jsonb),
  ('fieldstone', 'Fieldstone Home Care', 'Home and community care', '~350 caregivers', 'Prairies', 'Home-care provider that loses many new caregivers within their first year.', '~25 open roles (sample)', array['retention', 'transitions']::text[], 'yyyy?y??', false, '{"problems":[{"title":"Employee retention","detail":"Caregivers often take the job as a stopgap and leave when they find a better-fitting path."},{"title":"Career transitions","detail":"Many hires are career changers who haven''t explored whether care work suits them."}],"evidence":[{"text":"Careers page says \"no experience needed\" and recruits career changers.","source":"Website (sample)"},{"text":"Posts the same caregiver openings every month.","source":"Job postings (sample)"}],"unknowns":["What is their actual first-year turnover?","Does the owner or an HR manager decide on tools?"],"roles":["Director of Operations","HR Manager"],"fitConcerns":["Thin margins may limit budget."]}'::jsonb),
  ('summitcu', 'Summit Credit Union', 'Financial services', '~700 staff', 'Prairies', 'Regional credit union consolidating branches and moving tellers into advisory and digital roles.', '~15 open roles (sample)', array['retention', 'transitions']::text[], 'yyyy?y??', false, '{"problems":[{"title":"Employee retention","detail":"Branch consolidation can push experienced staff to leave if they don''t see a future role."},{"title":"Career transitions","detail":"Tellers are being asked to move into advisory or digital-support work that may not suit everyone."}],"evidence":[{"text":"Posted a \"Career Pathing Lead\" role in HR.","source":"Job posting (sample)"},{"text":"Closed three branches and opened a member contact centre.","source":"Member newsletter (sample)"}],"unknowns":["Has the Career Pathing Lead been hired, and what tools do they plan to use?","Is there a budget line for internal mobility?"],"roles":["Career Pathing Lead","Director of People","Chief Operating Officer"],"fitConcerns":["May already use a career-pathing feature in their HR software."]}'::jsonb),
  ('northgate', 'Northgate Polytechnic, Continuing Education', 'Post-secondary', '~4,000 adult learners a year', 'Western Canada', 'Continuing-education division serving mid-career adults who enroll to change or upgrade careers.', 'Few postings; growth is in new programs', array['transitions', 'reskilling']::text[], 'yyy??yn?', false, '{"problems":[{"title":"Career transitions","detail":"Adult learners often enroll without a clear target role, which can lead to program switching or non-completion."},{"title":"Reskilling","detail":"New short credentials show demand from workers who need to retrain, but choosing the right credential is left to the learner."}],"evidence":[{"text":"Launched four new micro-credential programs aimed at working adults this year.","source":"Program announcements (sample)"},{"text":"Career-advising page lists two advisors for the whole continuing-education division.","source":"Website (sample)"},{"text":"Program pages tell learners to explore their options first, but offer no tool for it.","source":"Website (sample)"}],"unknowns":["Does continuing education have its own budget for learner-support tools?","Who owns career advising for CE learners: the division or central career services?","Do they track non-completion, and is it a concern?"],"roles":["Director of Continuing Education","Manager, Learner Success","Career Services Manager"],"fitConcerns":["Post-secondary buying is slow: a stakeholder already cited bureaucracy, budget and long timelines.","Career services may see this as overlapping with existing advising."]}'::jsonb),
  ('westbrook', 'Westbrook College', 'Post-secondary', '~9,000 students', 'Western Canada', 'College where many first-year students switch out of health and business programs.', '~10 open roles (sample)', array['transitions', 'pipeline']::text[], 'yyy??yn?', false, '{"problems":[{"title":"Career transitions","detail":"Students switching programs cost tuition and time, and lower completion rates."},{"title":"Workforce pipeline","detail":"Health programs lose students who might have stayed with better early exploration."}],"evidence":[{"text":"Annual report lists program-transfer rates as a focus for next year.","source":"Annual report (sample)"},{"text":"Runs a first-year \"Explore\" seminar with no assessment tool.","source":"Website (sample)"}],"unknowns":["Which office owns retention: student services or the academic deans?","How long does a new tool take to approve?"],"roles":["Director, Student Success","Dean of Health","Career Centre Manager"],"fitConcerns":["Same buying-process risk as other post-secondary institutions."]}'::jsonb),
  ('cedarvalley', 'Cedar Valley Workforce Services', 'Non-profit employment services', '~60 staff, ~1,500 clients a year', 'Western Canada', 'Non-profit agency running government-funded programs for adults changing careers or returning to work.', 'Few postings', array['transitions', 'pipeline']::text[], 'yyn??yy?', false, '{"problems":[{"title":"Career transitions","detail":"Clients are adults between careers who need to work out what direction fits before choosing training."},{"title":"Workforce pipeline","detail":"Funders measure job placement, so better early direction could improve outcomes."}],"evidence":[{"text":"Runs a \"Career Decision-Making\" workshop series for adults.","source":"Program page (sample)"},{"text":"Annual report highlights clients who changed direction mid-program.","source":"Annual report (sample)"}],"unknowns":["Do program budgets allow buying a tool, or does it need funder approval?","Would counsellors use it with clients or would clients use it alone?"],"roles":["Executive Director","Program Manager, Career Transitions","Employment Counsellor (influencer)"],"fitConcerns":["Small organization, though it serves many adults.","Funding cycles may limit when they can buy."]}'::jsonb),
  ('aspenridge', 'Aspen Ridge Hotels', 'Hospitality', '~1,100 staff', 'Rocky Mountains', 'Resort hotel group with high seasonal turnover among young adult staff.', '~70 seasonal roles (sample)', array['retention']::text[], 'yyyy????', false, '{"problems":[{"title":"Employee retention","detail":"Seasonal staff rarely return, so the group re-hires and re-trains every year."}],"evidence":[{"text":"Advertises a \"grow your career with us\" program but few staff move into year-round roles.","source":"Website (sample)"},{"text":"Posts around 70 seasonal roles each spring.","source":"Job postings (sample)"}],"unknowns":["Is turnover seen as a problem or just a cost of seasonal work?","Who owns staff development: HR or each property?"],"roles":["Director of Human Resources","Talent Development Manager"],"fitConcerns":["They may accept turnover as normal for the industry."]}'::jsonb),
  ('helix', 'Helix Energy Services', 'Energy services', '~2,400 staff', 'Western Canada', 'Oilfield services company restructuring as clients shift toward lower-carbon projects.', 'Hiring in one division, cutting in two', array['transitions', 'reskilling']::text[], 'yyyy??n?', false, '{"problems":[{"title":"Career transitions","detail":"Restructuring means some staff must move into new kinds of work or leave the company."},{"title":"Reskilling","detail":"New service lines need people with different skills than the current workforce."}],"evidence":[{"text":"Announced a new division focused on carbon capture services.","source":"Investor update (sample)"},{"text":"Reported workforce reductions in two field locations.","source":"News article (sample)"}],"unknowns":["Do they offer outplacement or redeployment support today?","Is HR centralized or regional?"],"roles":["VP Human Resources","Talent Development Lead","Outplacement / Transition Program Lead"],"fitConcerns":["Outplacement is often bought from established firms through long procurement."]}'::jsonb),
  ('bowline', 'Bowline Logistics', 'Transportation & warehousing', '~900 staff', 'Prairies', 'Mid-size trucking and warehousing company automating parts of its warehouses.', '~30 open roles (sample)', array['reskilling', 'retention']::text[], 'yyyy????', false, '{"problems":[{"title":"Reskilling","detail":"Warehouse automation is changing roles; some workers need a path into maintenance, dispatch or supervision."},{"title":"Employee retention","detail":"Workers who can''t see a next step may leave during the transition."}],"evidence":[{"text":"Opened an automated distribution centre this year.","source":"News release (sample)"},{"text":"Careers page advertises \"grow with us\" but lists no development program.","source":"Website (sample)"}],"unknowns":["Is there an HR or training lead, or does the owner decide?","Are they building their own training ladder?"],"roles":["HR Manager","Operations Director","Owner / President"],"fitConcerns":["May build training in-house with their union."]}'::jsonb),
