  ('ridgeline', 'Ridgeline Staffing Group', 'Recruitment & staffing', '~120 staff', 'Western Canada', 'Staffing agency placing adults in light industrial and administrative roles.', 'Recruits for clients, not itself', array['pipeline']::text[], 'y?n??y??', false, '{"problems":[{"title":"Workforce pipeline","detail":"Placements that don''t fit the candidate end early, which costs the agency and the client."}],"evidence":[{"text":"Website promotes \"the right fit, the first time\" as a service promise.","source":"Website (sample)"}],"unknowns":["Do they use personality in matching at all?","Who decides on candidate-assessment tools?"],"roles":["Director of Operations","Recruitment Manager"],"fitConcerns":["A recruiter Joan spoke with didn''t use personality types in their process.","They may want a screening score, which Myrimaven does not offer."]}'::jsonb),
